const API_BASE = String(import.meta.env.VITE_API_URL || "/api").replace(/\/$/, "");
class ApiFailure extends Error { constructor(public fix: string, message: string) { super(message); } }
async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(`${API_BASE}${path}`, {
    ...init, credentials: "include",
    headers: { "Content-Type": "application/json", ...(init.headers || {}) },
  });
  if (!response.ok) {
    const body = await response.json().catch(() => ({})) as { message?: string; fix?: string };
    throw new ApiFailure(body.fix || "Check your connection and try again.", body.message || "The request did not go through.");
  }
  return response.status === 204 ? undefined as T : response.json() as Promise<T>;
}
const query = (params: Record<string, string | number | undefined>) => {
  const q = new URLSearchParams();
  Object.entries(params).forEach(([key, value]) => value !== undefined && q.set(key, String(value)));
  const text = q.toString();
  return text ? `?${text}` : "";
};

type Thread = {
  id: string; channel: string; subject: string | null; snippet: string; sender: string;
  unread: boolean; starred: boolean; last_message_at: string; category: string | null;
  opportunity_score: number; opportunity_kind: string | null; urgency: number;
  summary: string | null; action_items: string[];
};
type Detail = Thread & { messages: { id: string; author: string; sent_at: string; body: string }[] };
type Metric = { value: number | null; label: string; change_pct: number | null; confident: boolean; note: string | null };
type Contact = {
  id: string; display_name: string; company: string | null; title: string | null;
  tags: string[]; importance: number; relationship_strength: number; last_interaction_at: string | null;
  next_followup_at: string | null; days_silent: number | null; notes?: string | null; is_stale?: boolean;
};
type Source = { id: string; source_kind: string; display_name: string; status: string; last_synced_at: string | null; last_error: string | null };
type Rule = { id: string; name: string; enabled: boolean; trigger: { event: string; filters: { field: string; op: string; value: unknown }[] }; actions: { type: string; params: Record<string, unknown> }[]; run_count: number; last_run_at: string | null };

