function Assistant({ close }: { close: () => void }) {
  const [log, setLog] = useState<{ role: string; text: string }[]>([]);
  const [question, setQuestion] = useState(""); const [thinking, setThinking] = useState(false);
  const ask = async (text = question) => {
    if (!text.trim() || thinking) return; const q = text.trim(); setQuestion(""); setLog((l) => [...l, { role: "you", text: q }]); setThinking(true);
    try { const result = await request<{ answer: string }>("/v1/ai/assistant", { method: "POST", body: JSON.stringify({ question: q }) }); setLog((l) => [...l, { role: "assistant", text: result.answer }]); }
    catch (error) { setLog((l) => [...l, { role: "assistant", text: error instanceof ApiFailure ? `${error.message} ${error.fix}` : "That did not come back. Ask again." }]); }
    finally { setThinking(false); }
  };
  return <aside className="flex w-full shrink-0 flex-col border-l border-line bg-panel lg:w-96"><header className="flex items-center gap-2 border-b border-line px-4 py-3.5"><Sparkles size={13} className="text-iris" /><Mono className="text-paper">Assistant</Mono><button onClick={close} className="ml-auto p-1 text-faint hover:text-paper" aria-label="Close assistant"><X size={15} /></button></header><div className="flex-1 space-y-3 overflow-y-auto px-4 py-4">{log.length === 0 && <div className="space-y-2"><p className="mb-3 text-[13px] text-quiet">Ask anything about what is in your inbox right now.</p>{["What should I answer first today?", "Which relationships have gone cold?", "Summarise everything waiting on me."].map((starter) => <button key={starter} onClick={() => void ask(starter)} className="w-full rounded-lg border border-line bg-raise px-3 py-2.5 text-left text-xs text-quiet hover:text-paper">{starter}</button>)}</div>}{log.map((turn, index) => <div key={index} className={turn.role === "you" ? "rounded-lg border border-line bg-raise px-3.5 py-2.5 text-[13px] text-paper" : "glow rounded-lg border border-iris/25 px-3.5 py-2.5 text-[13px] leading-relaxed text-paper whitespace-pre-wrap"}>{turn.text}</div>)}{thinking && <Mono className="text-iris">Reading your inbox...</Mono>}</div><div className="border-t border-line p-3"><div className="flex gap-2 rounded-lg border border-line bg-raise px-3 py-2"><input value={question} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => event.key === "Enter" && void ask()} placeholder="Ask about your inbox..." aria-label="Ask the assistant" className="flex-1 bg-transparent text-[13px] text-paper outline-none placeholder:text-faint" /><button onClick={() => void ask()} disabled={thinking || !question.trim()} className="text-iris disabled:text-faint" aria-label="Send question"><Send size={14} /></button></div></div></aside>;
}
function Palette({ close }: { close: () => void }) {
  const [, navigate] = useLocation(); const [text, setText] = useState(""); const input = useRef<HTMLInputElement>(null);
  useEffect(() => input.current?.focus(), []);
  const destinations = NAV.filter((item) => item.label.toLowerCase().includes(text.toLowerCase()));
  return <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/55 px-4 pt-[12vh] backdrop-blur-sm" onClick={close}><div onClick={(event) => event.stopPropagation()} className="w-full max-w-lg overflow-hidden rounded-xl border border-line bg-raise shadow-2xl"><div className="flex items-center gap-3 border-b border-line px-4 py-3.5"><Search size={15} className="text-faint" /><input ref={input} value={text} onChange={(event) => setText(event.target.value)} onKeyDown={(event) => event.key === "Escape" && close()} placeholder="Search everything, or jump somewhere" className="flex-1 bg-transparent text-sm text-paper outline-none placeholder:text-faint" /><Mono className="text-faint">esc</Mono></div><div className="max-h-80 overflow-y-auto py-2"><Mono className="block px-4 py-1 text-faint">Navigate</Mono>{destinations.map((item) => <button key={item.href} onClick={() => { navigate(item.href); close(); }} className="flex w-full items-center gap-3 px-4 py-2.5 text-left text-[13px] text-paper hover:bg-panel"><ChevronRight size={13} className="text-faint" />{item.label}</button>)}{text && destinations.length === 0 && <p className="px-4 py-8 text-center text-[13px] text-quiet">Nothing matches "{text}".</p>}</div></div></div>;
}
function Shell({ children }: { children: ReactNode }) {
  const [location, navigate] = useLocation(); const [dark, setDark] = useState(true); const [assistant, setAssistant] = useState(false); const [palette, setPalette] = useState(false);
  useEffect(() => { document.documentElement.classList.toggle("light", !dark); }, [dark]);
  useEffect(() => { const handler = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key === "k") { event.preventDefault(); setPalette((value) => !value); } if (event.key === "Escape") setPalette(false); }; window.addEventListener("keydown", handler); return () => window.removeEventListener("keydown", handler); }, []);
  return <div className="flex min-h-[100dvh] w-full flex-col overflow-hidden lg:flex-row"><nav className="hidden w-[60px] shrink-0 flex-col items-center gap-1 border-r border-line bg-panel py-4 lg:flex"><Link href="/" className="mb-4 flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-iris to-mint"><span className="text-[13px] font-bold text-white">T</span></Link>{NAV.map(({ href, label: navLabel, Icon }) => <Link key={href} href={href} title={navLabel} className={`flex h-10 w-10 items-center justify-center rounded-lg ${location === href ? "bg-raise text-iris" : "text-faint hover:text-quiet"}`}><Icon size={17} /></Link>)}<div className="mt-auto flex flex-col gap-1"><button onClick={() => setDark((value) => !value)} className="flex h-10 w-10 items-center justify-center rounded-lg text-faint hover:text-quiet" aria-label="Toggle theme">{dark ? <Sun size={16} /> : <Moon size={16} />}</button><Link href="/settings" className="flex h-10 w-10 items-center justify-center rounded-lg text-faint hover:text-quiet" aria-label="Settings"><Settings size={16} /></Link></div></nav><div className="flex min-w-0 flex-1 flex-col"><header className="flex shrink-0 items-center gap-3 border-b border-line bg-panel px-4 py-3 lg:px-5"><Link href="/" className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-iris to-mint lg:hidden"><span className="text-[11px] font-bold text-white">T</span></Link><button onClick={() => setPalette(true)} className="flex max-w-sm flex-1 items-center gap-2.5 rounded-lg border border-line bg-raise px-3 py-1.5 text-left"><Search size={13} className="text-faint" /><span className="text-[13px] text-faint">Search everything</span><Mono className="ml-auto hidden text-faint sm:flex"><Command size={9} />K</Mono></button><button onClick={() => setDark((value) => !value)} className="p-2 text-faint lg:hidden" aria-label="Toggle theme">{dark ? <Sun size={16} /> : <Moon size={16} />}</button><button onClick={() => setAssistant((value) => !value)} className={`flex items-center gap-1.5 rounded-lg border border-iris/30 px-3 py-1.5 text-[13px] ${assistant ? "bg-iris text-white" : "bg-iris/10 text-iris"}`}><Sparkles size={13} /><span className="hidden sm:inline">Ask</span></button></header><div className="flex min-h-0 flex-1"><div className="flex min-w-0 flex-1">{children}</div>{assistant && <div className="hidden lg:flex"><Assistant close={() => setAssistant(false)} /></div>}</div><nav className="flex shrink-0 border-t border-line bg-panel lg:hidden">{NAV.slice(0, 5).map(({ href, label: navLabel, Icon }) => <Link key={href} href={href} className={`flex flex-1 flex-col items-center gap-1 py-2.5 ${location === href ? "text-iris" : "text-faint"}`}><Icon size={17} /><span className="font-mono text-[8px] uppercase tracking-wider">{navLabel}</span></Link>)}</nav></div>{assistant && <div className="fixed inset-0 z-40 flex flex-col bg-ink lg:hidden"><Assistant close={() => setAssistant(false)} /></div>}{palette && <Palette close={() => setPalette(false)} />}</div>;
}

