function Login() {
  const [email, setEmail] = useState(""); const [sent, setSent] = useState(false); const [sending, setSending] = useState(false); const [error, setError] = useState("");
  const submit = async () => { if (!email.includes("@")) { setError("That does not look like an email address."); return; } setSending(true); setError(""); await new Promise((resolve) => setTimeout(resolve, 600)); setSent(true); setSending(false); };
  return <main className="flex min-h-[100dvh]"><section className="hidden flex-1 flex-col justify-center border-r border-line bg-panel px-12 lg:flex"><Mono className="mb-6 text-faint">This morning, in one inbox</Mono><div className="flex h-56 items-end gap-3">{[94, 86, 81, 41, 4].map((score, index) => <div key={score} className="flex flex-1 flex-col items-center gap-2"><span className="font-mono text-xs text-quiet">{score}</span><div className={`animate-fill w-full rounded-t ${score >= 70 ? "bg-mint" : score >= 40 ? "bg-amber" : "bg-line"}`} style={{ height: `${score}%`, animationDelay: `${index * 90}ms` }} /><Mono className="text-faint">{["Investor", "Recruiter", "Client", "Review", "Newsletter"][index]}</Mono></div>)}</div><p className="mt-8 max-w-sm text-sm leading-relaxed text-quiet">Every other inbox sorts by when a message arrived. This one sorts by what acting on it is worth.</p></section><section className="flex flex-1 items-center justify-center px-6"><div className="w-full max-w-sm"><Link href="/" className="mb-8 flex h-9 w-9 items-center justify-center rounded-lg bg-gradient-to-br from-iris to-mint text-sm font-bold text-white">T</Link>{sent ? <><h1 className="mb-2 text-xl font-semibold tracking-tight">Check your email</h1><p className="text-sm text-quiet">A sign-in link is on its way to {email}. It works once and expires in fifteen minutes.</p></> : <><h1 className="mb-2 text-xl font-semibold tracking-tight">Sign in to Tryvanta Social</h1><p className="mb-6 text-sm text-quiet">No password. We send a link that signs you in.</p><input value={email} onChange={(event) => setEmail(event.target.value)} onKeyDown={(event) => event.key === "Enter" && void submit()} placeholder="you@company.com" className="mb-3 w-full rounded-lg border border-line bg-raise px-3.5 py-2.5 text-sm outline-none placeholder:text-faint focus:border-iris" />{error && <div className="mb-3 rounded-xl border border-ember/30 bg-ember/[.06] px-4 py-3 text-sm">{error}</div>}<Button primary onClick={() => void submit()} disabled={sending}><span className="flex items-center gap-2">{sending ? <Loader2 size={14} className="animate-spin" /> : <ArrowRight size={14} />}{sending ? "Sending" : "Send the link"}</span></Button><Link href="/" className="mt-6 block text-xs text-faint hover:text-quiet">Explore the demo workspace instead</Link></>}</div></section></main>;
}

function CommandPage() {
  const [threads, setThreads] = useState<Thread[]>([]); const [metrics, setMetrics] = useState<Record<string, Metric> | null>(null); const [error, setError] = useState<ApiFailure | null>(null);
  useEffect(() => { Promise.all([request<{ items: Thread[] }>("/v1/inbox?sort=opportunity&limit=40"), request<Record<string, Metric>>("/v1/analytics/overview")]).then(([page, overview]) => { setThreads(page.items || []); setMetrics(overview); }).catch((reason) => reason instanceof ApiFailure && setError(reason)); }, []);
  const top = [...threads].sort((a, b) => b.opportunity_score - a.opportunity_score).slice(0, 3); const urgent = [...threads].sort((a, b) => b.urgency - a.urgency).slice(0, 3); const worth = threads.filter((thread) => thread.opportunity_score >= 60).length;
  return <div className="flex-1 overflow-y-auto px-5 py-6 lg:px-8"><h1 className="text-2xl font-semibold tracking-tight">{new Date().toLocaleDateString(undefined, { weekday: "long" })} morning.</h1><p className="mb-6 text-sm text-quiet">{threads.length ? `${threads.length} threads waiting. ${worth} of them are worth your morning.` : "Nothing waiting. Connect a channel and this page starts working."}</p>{error && <div className="mb-4"><Failure error={error} /></div>}{threads.length > 0 && <section className="mb-3 rounded-xl border border-line bg-raise p-4"><div className="mb-3 flex items-baseline justify-between"><p className="text-sm text-quiet"><span className="text-2xl font-semibold text-paper">{worth}</span> of {threads.length} threads are worth acting on</p><Mono className="text-mint">{Math.round((worth / threads.length) * 100)}% signal</Mono></div><div className="flex h-8 gap-px overflow-hidden rounded-md">{[...threads].sort((a, b) => b.opportunity_score - a.opportunity_score).map((thread) => <div key={thread.id} title={`${thread.sender} · ${thread.opportunity_score}`} className={`flex-1 ${thread.urgency >= 85 && thread.opportunity_score < 50 ? "bg-ember" : thread.opportunity_score >= 70 ? "bg-mint" : thread.opportunity_score >= 40 ? "bg-amber" : "bg-line"}`} style={{ opacity: .25 + thread.opportunity_score / 100 * .75 }} />)}</div></section>}<div className="grid gap-4 lg:grid-cols-2"><SignalList title="Worth the most" icon={<TrendingUp size={13} />} color="text-mint" items={top} score /><SignalList title="Decaying fastest" icon={<AlertTriangle size={13} />} color="text-ember" items={urgent} /></div>{metrics && <div className="mt-4 grid grid-cols-2 gap-3 lg:grid-cols-4">{Object.entries(metrics).map(([key, metric]) => <div key={key} className="rounded-xl border border-line bg-raise p-4"><Mono className="text-faint">{metric.label}</Mono><p className="mt-1 text-xl font-semibold">{metric.value === null ? "—" : key === "pipeline_usd" ? `$${Math.round(metric.value)}` : metric.value.toLocaleString()}</p>{metric.change_pct !== null && <Mono className={metric.change_pct >= 0 ? "text-mint" : "text-ember"}>{metric.change_pct >= 0 ? "+" : ""}{metric.change_pct}%</Mono>}</div>)}</div>}</div>;
}
function SignalList({ title, icon, color, items, score = false }: { title: string; icon: ReactNode; color: string; items: Thread[]; score?: boolean }) {
  return <section className="rounded-xl border border-line bg-raise p-4"><div className={`mb-3 flex items-center gap-2 ${color}`}>{icon}<Mono>{title}</Mono></div>{items.map((thread) => <Link key={thread.id} href={`/inbox?thread=${thread.id}`} className="flex items-start gap-3 border-t border-line-soft py-2.5">{score ? <span className="min-w-[24px] font-mono text-[13px] text-mint">{thread.opportunity_score}</span> : <Clock size={13} className="mt-0.5 shrink-0 text-ember" />}<span className="min-w-0"><span className="block truncate text-[13px]">{thread.subject || thread.sender}</span><span className="block truncate text-xs text-quiet">{thread.summary || thread.snippet}</span></span></Link>)}{items.length === 0 && <p className="py-6 text-center text-xs text-quiet">Nothing here yet.</p>}</section>;
}

function ThreadRow({ thread, active, index, select }: { thread: Thread; active: boolean; index: number; select: () => void }) {
  const { Icon, hue, label: channelLabel } = infoFor(thread.channel); const alarming = thread.urgency >= 85 && thread.opportunity_score < 50;
  return <button onClick={select} aria-current={active} style={{ animationDelay: `${Math.min(index, 12) * 28}ms` }} className={`flex w-full animate-rise gap-3 rounded-xl border px-3 py-3 text-left ${active ? "border-line bg-raise" : "border-transparent hover:bg-raise/60"}`}><SignalRail score={thread.opportunity_score} negative={alarming} /><div className="min-w-0 flex-1"><div className="mb-1 flex items-center gap-2"><Icon size={12} style={{ color: hue }} /><span className={`truncate text-sm ${thread.unread ? "font-medium" : "text-quiet"}`}>{thread.sender}</span>{thread.unread && <span className="h-1.5 w-1.5 rounded-full bg-iris" /> }<Mono className="ml-auto shrink-0 text-faint">{relativeTime(thread.last_message_at)}</Mono></div><p className={`mb-1.5 truncate text-[13px] ${thread.unread ? "text-paper" : "text-quiet"}`}>{thread.subject || thread.snippet}</p><div className="flex items-center gap-1.5"><Chip tone={alarming ? "ember" : thread.opportunity_score >= 70 ? "mint" : "quiet"}>{thread.opportunity_score}</Chip><Mono className="text-faint">{label(thread.category)}</Mono></div></div></button>;
}
function ThreadPane({ thread, close, stateChange }: { thread: Detail | null; close: () => void; stateChange: (state: string) => void }) {
  const [tone, setTone] = useState("professional"); const [draft, setDraft] = useState(""); const [writing, setWriting] = useState(false); const [error, setError] = useState<ApiFailure | null>(null);
  useEffect(() => { setDraft(""); setError(null); }, [thread?.id]);
  const write = async (nextTone: string) => { if (!thread) return; setTone(nextTone); setWriting(true); try { const result = await request<{ body: string }>(`/v1/inbox/${thread.id}/draft`, { method: "POST", body: JSON.stringify({ tone: nextTone }) }); setDraft(result.body); } catch (reason) { reason instanceof ApiFailure && setError(reason); } finally { setWriting(false); } };
  if (!thread) return <div className="flex flex-1 items-center justify-center bg-panel"><Empty icon={<InboxIcon size={28} />} title="Pick a thread to see what it is worth." /></div>;
  const { Icon, hue, label: channelLabel } = infoFor(thread.channel); const alarming = thread.urgency >= 85 && thread.opportunity_score < 50;
  return <article className="flex-1 overflow-y-auto bg-panel"><header className="sticky top-0 z-10 border-b border-line bg-panel/95 px-5 py-4 backdrop-blur"><div className="mb-2 flex items-center gap-2"><button onClick={close} className="p-1 text-quiet lg:hidden" aria-label="Back"><CornerUpLeft size={16} /></button><Icon size={13} style={{ color: hue }} /><Mono className="text-faint">{channelLabel} · {relativeTime(thread.last_message_at)}</Mono><div className="ml-auto flex gap-1"><button className="p-1.5 text-faint" aria-label="Star"><Star size={14} /></button><button onClick={() => stateChange("archived")} className="p-1.5 text-faint" aria-label="Archive"><Archive size={14} /></button></div></div><h1 className="text-lg font-semibold leading-snug">{thread.subject || "(no subject)"}</h1><p className="mt-0.5 text-[13px] text-quiet">{thread.sender}</p></header><div className="px-5 py-4">{thread.summary && <section className="glow mb-5 rounded-xl border border-iris/20 p-4"><div className="mb-2.5 flex items-center gap-2"><Sparkles size={12} className="text-iris" /><Mono className="text-iris">Read before you did</Mono></div><p className="mb-3 text-[13px] leading-relaxed">{thread.summary}</p><div className="mb-3 flex gap-4">{[["Opportunity", thread.opportunity_score, "bg-mint", "text-mint"], ["Urgency", thread.urgency, alarming ? "bg-ember" : "bg-amber", alarming ? "text-ember" : "text-amber"]].map(([metric, value, bg, fg]) => <div key={String(metric)} className="flex-1"><Mono className="text-faint">{metric}</Mono><div className="mt-1 flex items-center gap-2"><div className="h-1 flex-1 rounded-full bg-line-soft"><div className={`h-1 rounded-full ${bg}`} style={{ width: `${Number(value)}%` }} /></div><Mono className={String(fg)}>{value}</Mono></div></div>)}</div>{thread.action_items.length > 0 && <ul className="space-y-1.5">{thread.action_items.map((item) => <li key={item} className="flex gap-2 text-xs text-quiet"><Check size={12} className="text-mint" />{item}</li>)}</ul>}</section>}<div className="mb-6 space-y-4">{thread.messages.map((message) => <div key={message.id}><Mono className="text-faint">{message.author} · {relativeTime(message.sent_at)}</Mono><p className="mt-1 whitespace-pre-wrap text-sm leading-relaxed">{message.body}</p></div>)}</div><section className="overflow-hidden rounded-xl border border-line bg-raise"><div className="flex gap-1.5 overflow-x-auto border-b border-line px-3 py-2.5">{["professional", "casual", "confident", "founder", "sales", "support"].map((item) => <Chip key={item} tone="iris" active={tone === item} onClick={() => void write(item)}>{item}</Chip>)}</div><textarea value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={writing ? "" : "Pick a tone above, or write it yourself."} rows={draft ? 6 : 4} className="w-full resize-none bg-transparent px-4 py-3 text-[13px] leading-relaxed outline-none placeholder:text-faint" />{writing && <div className="px-4 pb-3"><Mono className="text-iris">Writing in your voice...</Mono></div>}{error && <div className="px-4 pb-3"><Failure error={error} /></div>}<div className="flex gap-2 border-t border-line px-3 py-2.5"><Button primary small disabled={!draft}>Send reply</Button><Button small disabled={!draft} onClick={() => setDraft("")}>Clear</Button><button disabled={!draft} onClick={() => navigator.clipboard?.writeText(draft)} className="ml-auto p-1.5 text-faint disabled:opacity-40" aria-label="Copy draft"><Copy size={14} /></button></div></section></div></article>;
}
function Inbox() {
  const [, params] = useRoute("/inbox"); const search = new URLSearchParams(window.location.search); const [threads, setThreads] = useState<Thread[]>([]); const [selected, setSelected] = useState<string | null>(search.get("thread")); const [detail, setDetail] = useState<Detail | null>(null); const [filter, setFilter] = useState("all"); const [loading, setLoading] = useState(true); const [error, setError] = useState<ApiFailure | null>(null);
  const load = useCallback(async () => { setLoading(true); try { const result = await request<{ items: Thread[] }>(`/v1/inbox${query({ sort: filter === "urgent" ? "urgency" : "opportunity", min_opportunity: filter === "opportunity" ? 60 : undefined, limit: 100 })}`); setThreads(result.items || []); } catch (reason) { reason instanceof ApiFailure && setError(reason); } finally { setLoading(false); } }, [filter]);
  useEffect(() => { void load(); }, [load]); useEffect(() => { if (!selected) { setDetail(null); return; } request<Detail>(`/v1/inbox/${selected}`).then(setDetail).catch(() => setDetail(null)); }, [selected]);
  const visible = useMemo(() => filter === "urgent" ? threads.filter((thread) => thread.urgency >= 70) : filter === "unread" ? threads.filter((thread) => thread.unread) : threads, [threads, filter]);
  const changeState = async (id: string, state: string) => { try { await request(`/v1/inbox/${id}/state`, { method: "POST", body: JSON.stringify({ state }) }); setThreads((current) => current.filter((thread) => thread.id !== id)); setSelected(null); } catch (reason) { reason instanceof ApiFailure && setError(reason); } };
  return <><section className={`${selected ? "hidden lg:flex" : "flex"} w-full shrink-0 flex-col border-r border-line bg-panel lg:w-80`}><div className="flex gap-1.5 overflow-x-auto border-b border-line px-3 pb-2 pt-3">{["all", "opportunity", "urgent", "unread"].map((item) => <Chip key={item} tone={item === "opportunity" ? "mint" : item === "urgent" ? "ember" : "quiet"} active={filter === item} onClick={() => setFilter(item)}>{item}</Chip>)}</div><div className="flex-1 overflow-y-auto px-2 py-2">{error && <div className="p-2"><Failure error={error} /></div>}{loading && <div className="flex justify-center py-12"><Loader2 size={16} className="animate-spin text-faint" /></div>}{!loading && visible.length === 0 && <Empty icon={<InboxIcon size={22} />} title="No threads" />}{visible.map((thread, index) => <ThreadRow key={thread.id} thread={thread} index={index} active={selected === thread.id} select={() => setSelected(thread.id)} />)}</div></section><ThreadPane thread={detail} close={() => setSelected(null)} stateChange={(state) => selected && void changeState(selected, state)} /></>;
}

const FORMATS = [
  ["linkedin_post", "LinkedIn post", "150–250 words, one idea"], ["x_thread", "X thread", "5–8 posts, first post stands alone"],
  ["instagram_caption", "Instagram caption", "Under 125 words before the fold"], ["facebook_post", "Facebook post", "80–150 words, conversational"],
  ["newsletter", "Newsletter intro", "Open with the single most useful sentence"], ["email_campaign", "Email campaign", "Under 150 words, one clear CTA"],
  ["blog_article", "Blog article", "700–1000 words with subheadings"], ["product_launch", "Product launch", "What it does, who it is for, what changed"],
];
function Studio() {
  const [format, setFormat] = useState("linkedin_post"); const [tone, setTone] = useState("confident"); const [brief, setBrief] = useState(""); const [variants, setVariants] = useState<{ angle: string; body: string; hashtags: string[] }[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState<ApiFailure | null>(null); const [saved, setSaved] = useState("");
  const generate = async () => { if (!brief.trim()) return; setBusy(true); setError(null); setVariants([]); try { setVariants(await request(`/v1/ai/content`, { method: "POST", body: JSON.stringify({ kind: format, brief, tone, variants: 3 }) })); } catch (reason) { reason instanceof ApiFailure && setError(reason); } finally { setBusy(false); } };
  const save = async (body: string) => { try { await request("/v1/content", { method: "POST", body: JSON.stringify({ kind: format, body }) }); setSaved(body.slice(0, 40)); } catch (reason) { reason instanceof ApiFailure && setError(reason); } };
  return <div className="flex-1 overflow-y-auto px-5 py-6 lg:px-8"><h1 className="mb-1 text-xl font-semibold tracking-tight">Content Studio</h1><p className="mb-6 text-sm text-quiet">One brief. Three different angles. Pick the one that fits.</p><div className="mb-4 flex flex-wrap gap-1.5">{FORMATS.map(([id, name]) => <Chip key={id} tone="iris" active={format === id} onClick={() => setFormat(id)}>{name}</Chip>)}</div><div className="mb-4 flex gap-1.5">{["confident", "casual", "professional", "founder", "sales"].map((item) => <Chip key={item} active={tone === item} onClick={() => setTone(item)}>{item}</Chip>)}</div><div className="mb-6 overflow-hidden rounded-xl border border-line bg-raise"><textarea value={brief} onChange={(event) => setBrief(event.target.value)} onKeyDown={(event) => (event.metaKey || event.ctrlKey) && event.key === "Enter" && void generate()} placeholder="What happened this week that is worth telling people about?" rows={3} className="w-full resize-none bg-transparent px-4 py-3 text-[14px] outline-none placeholder:text-faint" /><div className="flex items-center gap-3 border-t border-line px-3 py-2.5"><Button primary small onClick={() => void generate()} disabled={busy || !brief.trim()}><span className="flex items-center gap-1.5">{busy ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />}{busy ? "Writing..." : "Write three versions"}</span></Button><Mono className="text-faint">{FORMATS.find(([id]) => id === format)?.[2]}</Mono></div></div>{error && <div className="mb-6"><Failure error={error} /></div>}{saved && <div className="mb-4 rounded-lg border border-mint/25 bg-mint/[.06] px-3 py-2 text-[13px] text-quiet"><Check size={13} className="mr-2 inline text-mint" />Saved draft: <span className="text-paper">"{saved}..."</span></div>}{busy && <div className="flex justify-center py-16"><Mono className="text-iris">Drafting three angles...</Mono></div>}{!busy && variants.length === 0 && !error && <Empty icon={<PenLine size={24} />} title="Describe the week and it will find the angle. Nothing is scheduled until you pick one." />}{variants.length > 0 && <div className="grid gap-4 lg:grid-cols-3">{variants.map((variant, index) => <article key={index} className="flex flex-col rounded-xl border border-line bg-raise p-4"><div className="mb-3 flex items-center gap-2"><Mono className="text-iris">0{index + 1}</Mono><span className="text-[13px] font-medium">{variant.angle}</span></div><p className="flex-1 whitespace-pre-wrap text-[13px] leading-relaxed text-quiet">{variant.body}</p>{variant.hashtags?.length > 0 && <div className="mt-3 flex flex-wrap gap-1.5"><Mono className="text-mint">{variant.hashtags.join(" ")}</Mono></div>}<div className="mt-4 flex gap-2 border-t border-line pt-3"><Button primary small onClick={() => void save(variant.body)}><Clock size={12} className="mr-1 inline" />Save draft</Button><Button small onClick={() => navigator.clipboard?.writeText(variant.body)}><Copy size={12} className="mr-1 inline" />Copy</Button></div></article>)}</div>}</div>;
}

function People() {
  const [contacts, setContacts] = useState<Contact[]>([]); const [selected, setSelected] = useState<Contact | null>(null); const [sort, setSort] = useState("decay_risk"); const [loading, setLoading] = useState(true); const [error, setError] = useState<ApiFailure | null>(null);
  useEffect(() => { setLoading(true); request<Contact[]>(`/v1/contacts${query({ sort })}`).then(setContacts).catch((reason) => reason instanceof ApiFailure && setError(reason)).finally(() => setLoading(false)); }, [sort]);
  return <><section className={`${selected ? "hidden lg:flex" : "flex"} w-full shrink-0 flex-col border-r border-line bg-panel lg:w-80`}><div className="flex items-center gap-2 border-b border-line px-3 py-3"><Users size={14} className="text-faint" /><Mono className="text-faint">Sort:</Mono><div className="flex gap-1 overflow-x-auto">{["decay_risk", "strength", "importance", "recent", "name"].map((item) => <Chip key={item} active={sort === item} onClick={() => setSort(item)}>{item.replace("_", " ")}</Chip>)}</div></div><div className="flex-1 space-y-0.5 overflow-y-auto px-2 py-2">{error && <Failure error={error} />}{loading && <div className="flex justify-center py-12"><Loader2 size={16} className="animate-spin text-faint" /></div>}{!loading && contacts.length === 0 && !error && <Empty icon={<Users size={22} />} title="Nobody here yet. Contacts are created automatically as messages arrive." />}{contacts.map((contact) => <button key={contact.id} onClick={() => setSelected(contact)} className={`flex w-full items-center gap-3 rounded-xl border px-3 py-3 text-left ${selected?.id === contact.id ? "border-line bg-raise" : "border-transparent hover:bg-raise/60"}`}><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-iris/10 text-xs font-semibold text-iris">{contact.display_name.split(" ").map((word) => word[0]).join("").slice(0, 2)}</span><span className="min-w-0 flex-1"><span className="block truncate text-[13px] font-medium">{contact.display_name}</span><Mono className="text-faint">{[contact.company, ...contact.tags.slice(0, 1)].filter(Boolean).join(" · ")}</Mono></span><span className="shrink-0 text-right"><div className="h-1 w-16 rounded-full bg-line-soft"><div className={`h-1 rounded-full ${contact.relationship_strength >= 65 ? "bg-mint" : contact.relationship_strength >= 35 ? "bg-amber" : "bg-ember"}`} style={{ width: `${contact.relationship_strength}%` }} /></div><Mono className="text-faint">{contact.days_silent === null ? "—" : `${contact.days_silent}d silent`}</Mono></span></button>)}</div></section><ContactPane contact={selected} back={() => setSelected(null)} /></>;
}
function ContactPane({ contact, back }: { contact: Contact | null; back: () => void }) {
  const [note, setNote] = useState(""); const [timeline, setTimeline] = useState<{ thread_id: string; channel: string; body: string; sent_at: string }[]>([]); const [saving, setSaving] = useState(false);
  useEffect(() => { if (!contact) return; setNote(contact.notes || ""); request<typeof timeline>(`/v1/contacts/${contact.id}/timeline`).then(setTimeline).catch(() => setTimeline([])); }, [contact?.id]);
  const save = async () => { if (!contact) return; setSaving(true); try { await request(`/v1/contacts/${contact.id}`, { method: "PATCH", body: JSON.stringify({ notes: note }) }); } finally { setSaving(false); } };
  if (!contact) return <div className="flex flex-1 items-center justify-center bg-panel"><Empty icon={<Users size={24} />} title="Pick a person to see the full picture." /></div>;
  return <article className="flex-1 overflow-y-auto bg-panel"><header className="sticky top-0 z-10 border-b border-line bg-panel/95 px-5 py-4 backdrop-blur"><button onClick={back} className="mb-2 p-1 text-quiet lg:hidden" aria-label="Back"><ArrowLeft size={16} /></button><div className="flex items-start gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-full bg-iris/10 text-sm font-semibold text-iris">{contact.display_name.split(" ").map((word) => word[0]).join("").slice(0, 2)}</span><div><h1 className="text-lg font-semibold">{contact.display_name}</h1><Mono className="text-faint">{[contact.company, contact.title].filter(Boolean).join(" · ")}</Mono></div></div></header><div className="space-y-6 px-5 py-4"><div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{[["Importance", contact.importance, "text-iris"], ["Strength", contact.relationship_strength, "text-mint"], ["Days silent", contact.days_silent ?? "—", "text-quiet"]].map(([name, value, color]) => <div key={String(name)} className="rounded-lg border border-line bg-raise p-3"><Mono className="text-faint">{name}</Mono><p className={`mt-1 text-xl font-semibold ${color}`}>{value}</p></div>)}</div>{contact.tags.length > 0 && <div className="flex flex-wrap gap-1.5">{contact.tags.map((tag) => <Chip key={tag}>{tag}</Chip>)}</div>}<section><Mono className="mb-2 text-faint">Notes</Mono><textarea value={note} onChange={(event) => setNote(event.target.value)} rows={3} className="w-full resize-none rounded-lg border border-line bg-raise px-3 py-2.5 text-[13px] outline-none placeholder:text-faint focus:border-iris" placeholder="Anything worth remembering about this relationship." /><div className="mt-2"><Button small onClick={() => void save()} disabled={saving}>{saving ? "Saving..." : "Save note"}</Button></div></section><section><Mono className="mb-3 text-faint">History</Mono>{timeline.length === 0 ? <p className="text-sm text-quiet">No conversation history yet.</p> : <div className="space-y-3">{timeline.map((entry) => <div key={`${entry.thread_id}-${entry.sent_at}`} className="rounded-lg border border-line bg-raise px-3.5 py-3"><Mono className="text-faint">{entry.channel} · {relativeTime(entry.sent_at)}</Mono><p className="mt-1 line-clamp-2 text-[13px] text-quiet">{entry.body}</p></div>)}</div>}</section></div></article>;
}

const starterRules = [
  { name: "Recruiter with a real role", trigger: { event: "object.scored", filters: [{ field: "category", op: "eq", value: "recruiter" }] }, actions: [{ type: "notify", params: { priority: "high" } }] },
  { name: "Review drops below three stars", trigger: { event: "object.scored", filters: [{ field: "sentiment", op: "eq", value: "negative" }] }, actions: [{ type: "draft_reply", params: { tone: "support" } }] },
];
function Rules() {
  const [rules, setRules] = useState<Rule[]>([]); const [building, setBuilding] = useState(false); const [expanded, setExpanded] = useState<string | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState<ApiFailure | null>(null);
  const load = useCallback(() => { setLoading(true); Promise.all([request<Rule[]>("/v1/automations"), request<{ events: string[]; fields: string[]; actions: string[] }>("/v1/automations/vocabulary")]).then(([items]) => setRules(items)).catch((reason) => reason instanceof ApiFailure && setError(reason)).finally(() => setLoading(false)); }, []);
  useEffect(() => { void load(); }, [load]);
  const toggle = async (rule: Rule) => { try { const next = await request<Rule>(`/v1/automations/${rule.id}`, { method: "PATCH", body: JSON.stringify({ enabled: !rule.enabled }) }); setRules((items) => items.map((item) => item.id === rule.id ? next : item)); } catch (reason) { reason instanceof ApiFailure && setError(reason); } };
  const remove = async (id: string) => { try { await request(`/v1/automations/${id}`, { method: "DELETE" }); setRules((items) => items.filter((item) => item.id !== id)); } catch (reason) { reason instanceof ApiFailure && setError(reason); } };
  const add = async (starter: typeof starterRules[number]) => { try { const created = await request<Rule>("/v1/automations", { method: "POST", body: JSON.stringify(starter) }); setRules((items) => [created, ...items]); } catch (reason) { reason instanceof ApiFailure && setError(reason); } };
  return <div className="flex-1 overflow-y-auto px-5 py-6 lg:px-8"><div className="mb-6 flex items-start justify-between"><div><h1 className="mb-1 text-xl font-semibold">Rules</h1><p className="text-sm text-quiet">Runs while you sleep. Rules only fire on facts the system can see.</p></div><Button primary small onClick={() => setBuilding((value) => !value)}><Plus size={13} className="mr-1 inline" />New rule</Button></div>{error && <div className="mb-5"><Failure error={error} /></div>}{building && <RuleBuilder close={() => setBuilding(false)} created={(rule) => { setRules((items) => [rule, ...items]); setBuilding(false); }} />}{loading && <div className="flex justify-center py-12"><Loader2 size={16} className="animate-spin text-faint" /></div>}{!loading && rules.length === 0 && <><Empty icon={<Workflow size={24} />} title="No rules yet. Try one of these to start." /><div className="mt-4 grid gap-3 lg:grid-cols-2">{starterRules.map((starter) => <button key={starter.name} onClick={() => void add(starter)} className="rounded-xl border border-line bg-raise p-4 text-left hover:border-iris/40"><p className="mb-1 text-[13px] font-medium">{starter.name}</p><p className="text-xs text-quiet">{starter.actions.map((action) => action.type).join(" · ")}</p></button>)}</div></>}<div className="mt-4 space-y-3">{rules.map((rule) => <article key={rule.id} className="rounded-xl border border-line bg-raise"><div className="flex items-center gap-3 p-4"><button onClick={() => void toggle(rule)} role="switch" aria-checked={rule.enabled} className={`relative h-[18px] w-8 rounded-full ${rule.enabled ? "bg-mint" : "bg-line"}`}><span className={`absolute top-[2px] h-3.5 w-3.5 rounded-full bg-white ${rule.enabled ? "left-4" : "left-0.5"}`} /></button><span className="min-w-0 flex-1 text-[13px] font-medium">{rule.name}</span><Mono className="text-faint">{rule.run_count} runs</Mono><button onClick={() => setExpanded((value) => value === rule.id ? null : rule.id)} className="p-1 text-faint" aria-label="Expand rule">{expanded === rule.id ? <ChevronDown size={15} /> : <ChevronRight size={15} />}</button><button onClick={() => void remove(rule.id)} className="p-1 text-faint hover:text-ember" aria-label="Delete rule"><Trash2 size={14} /></button></div>{expanded === rule.id && <div className="space-y-2 border-t border-line px-4 pb-4 pt-3"><div className="flex gap-2"><Mono className="w-12 text-amber">WHEN</Mono><span className="text-[12px] text-quiet">{rule.trigger.event} — {rule.trigger.filters.map((item) => `${item.field} ${item.op} ${item.value}`).join(" and ") || "always"}</span></div>{rule.actions.map((action, index) => <div className="flex gap-2" key={index}><Mono className="w-12 text-mint">THEN</Mono><span className="text-[12px] text-quiet">{action.type}</span></div>)}</div>}</article>)}</div></div>;
}
function RuleBuilder({ close, created }: { close: () => void; created: (rule: Rule) => void }) {
  const [name, setName] = useState(""); const [value, setValue] = useState(""); const [busy, setBusy] = useState(false);
  const save = async () => { if (!name.trim() || !value.trim()) return; setBusy(true); try { const rule = await request<Rule>("/v1/automations", { method: "POST", body: JSON.stringify({ name, trigger: { event: "object.scored", filters: [{ field: "category", op: "eq", value }] }, actions: [{ type: "notify", params: {} }] }) }); created(rule); } catch { } finally { setBusy(false); } };
  return <div className="mb-6 rounded-xl border border-iris/30 bg-raise p-5"><div className="mb-4 flex items-center gap-2"><Sparkles size={13} className="text-iris" /><span className="text-[13px] font-medium">New rule</span><button onClick={close} className="ml-auto text-xs text-faint">Cancel</button></div><div className="space-y-3"><input value={name} onChange={(event) => setName(event.target.value)} placeholder="Recruiters worth answering" className="w-full rounded-lg border border-line bg-panel px-3 py-2 text-[13px] outline-none focus:border-iris" /><div className="grid grid-cols-2 gap-3"><div><label className="mb-1 block text-xs text-quiet">When field</label><input value="category" readOnly className="w-full rounded-lg border border-line bg-panel px-3 py-2 text-[13px] text-quiet" /></div><div><label className="mb-1 block text-xs text-quiet">Equals</label><input value={value} onChange={(event) => setValue(event.target.value)} placeholder="recruiter" className="w-full rounded-lg border border-line bg-panel px-3 py-2 text-[13px] outline-none focus:border-iris" /></div></div><Button primary small onClick={() => void save()} disabled={busy || !name.trim() || !value.trim()}>{busy ? "Saving..." : "Create rule"}</Button></div></div>;
}

function DataPage() {
  const [overview, setOverview] = useState<Record<string, Metric> | null>(null);
  const [channels, setChannels] = useState<{ channel: string; opportunities: number }[]>([]);
  const [growth, setGrowth] = useState<{ week: string; threads: number; opportunities: number }[]>([]);
  const [loading, setLoading] = useState(true); const [error, setError] = useState<ApiFailure | null>(null);
  useEffect(() => { Promise.all([request<Record<string, Metric>>("/v1/analytics/overview"), request<{ channel: string; opportunities: number }[]>("/v1/analytics/channels"), request<typeof growth>("/v1/analytics/growth")]).then(([metrics, channelRows, growthRows]) => { setOverview(metrics); setChannels(channelRows); setGrowth(growthRows); }).catch((reason) => reason instanceof ApiFailure && setError(reason)).finally(() => setLoading(false)); }, []);
  if (loading) return <div className="flex flex-1 items-center justify-center"><Loader2 size={18} className="animate-spin text-faint" /></div>;
  return <div className="flex-1 overflow-y-auto px-5 py-6 lg:px-8"><h1 className="mb-1 text-xl font-semibold tracking-tight">Data</h1><p className="mb-6 text-sm text-quiet">Reach is vanity until it becomes a thread in the inbox.</p>{error && <div className="mb-5"><Failure error={error} /></div>}{overview && <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">{Object.entries(overview).map(([key, metric]) => <div key={key} className="rounded-xl border border-line bg-raise p-4"><Mono className="text-faint">{metric.label}</Mono><p className="mt-1 text-2xl font-semibold">{metric.value === null ? "—" : key === "pipeline_usd" ? `$${Math.round(metric.value)}` : key === "response_time" ? `${metric.value}h` : metric.value.toLocaleString()}</p>{metric.change_pct !== null && <Mono className={metric.change_pct >= 0 ? "text-mint" : "text-ember"}>{metric.change_pct >= 0 ? "+" : ""}{metric.change_pct}%</Mono>}</div>)}</div>}<div className="grid gap-4 lg:grid-cols-2"><section className="rounded-xl border border-line bg-raise p-4"><Mono className="mb-4 text-faint">Weekly volume vs opportunities</Mono>{growth.length === 0 ? <Empty icon={<TrendingUp size={20} />} title="Not enough data yet. Keep using the inbox and this fills in." /> : <div className="space-y-3">{growth.slice(-10).map((point) => <div key={point.week} className="flex items-center gap-3"><Mono className="w-20 text-faint">{point.week}</Mono><div className="h-2 flex-1 rounded-full bg-line-soft"><div className="h-2 rounded-full bg-iris" style={{ width: `${Math.min(point.threads * 4, 100)}%` }} /></div><Mono className="text-paper">{point.opportunities}</Mono></div>)}</div>}</section><section className="rounded-xl border border-line bg-raise p-4"><Mono className="mb-4 text-faint">Where opportunities actually come from</Mono>{channels.length === 0 ? <Empty icon={<TrendingUp size={20} />} title="Connect more sources and this chart becomes meaningful." /> : <div className="space-y-3">{channels.map((item, index) => <div key={item.channel} className="flex items-center gap-3"><Mono className="w-24 truncate text-faint">{item.channel}</Mono><div className="h-3 flex-1 rounded-full bg-line-soft"><div className={`h-3 rounded-full ${index === 0 ? "bg-mint" : "bg-mint/60"}`} style={{ width: `${Math.min(item.opportunities * 8, 100)}%` }} /></div><Mono className="text-paper">{item.opportunities}</Mono></div>)}</div>}</section></div><p className="mt-6 text-[11px] leading-relaxed text-faint">Pipeline values are first-touch estimates extracted from message text. Useful for ranking where your attention pays off — not for forecasting revenue.</p></div>;
}

function SettingsPage() {
  const [sources, setSources] = useState<Source[]>([]); const [available, setAvailable] = useState<{ kind: string; configured: boolean }[]>([]); const [adding, setAdding] = useState(false); const [loading, setLoading] = useState(true); const [error, setError] = useState<ApiFailure | null>(null);
  const load = useCallback(() => { setLoading(true); Promise.all([request<Source[]>("/v1/channels"), request<{ channels: { kind: string; configured: boolean }[] }>("/v1/meta")]).then(([accounts, meta]) => { setSources(accounts); setAvailable(meta.channels); }).catch((reason) => reason instanceof ApiFailure && setError(reason)).finally(() => setLoading(false)); }, []);
  useEffect(() => { void load(); }, [load]);
  const connect = async (kind: string) => { try { const result = await request<{ authorize_url: string }>(`/v1/channels/${kind}/connect`); window.location.href = result.authorize_url; } catch (reason) { reason instanceof ApiFailure && setError(reason); } };
  const disconnect = async (id: string) => { if (!window.confirm("Disconnect this source? Messages already imported stay in the inbox.")) return; try { await request(`/v1/channels/${id}`, { method: "DELETE" }); setSources((items) => items.filter((item) => item.id !== id)); } catch (reason) { reason instanceof ApiFailure && setError(reason); } };
  return <div className="flex-1 overflow-y-auto px-5 py-6 lg:px-8"><h1 className="mb-1 text-xl font-semibold">Settings</h1><p className="mb-6 text-sm text-quiet">Manage connected sources and workspace preferences.</p>{error && <div className="mb-6"><Failure error={error} /></div>}<section className="mb-8"><div className="mb-3 flex items-center justify-between"><Mono className="text-faint">Connected sources</Mono><Button small primary onClick={() => setAdding((value) => !value)}><Plus size={13} className="mr-1 inline" />Add source</Button></div>{loading && <div className="flex justify-center py-8"><Loader2 size={16} className="animate-spin text-faint" /></div>}{!loading && sources.length === 0 && <Empty icon={<Globe size={22} />} title="No sources connected yet. Add one and your inbox starts filling." action={<Button primary onClick={() => setAdding(true)}>Connect your first source</Button>} />}<div className="space-y-2">{sources.map((source) => { const info = infoFor(source.source_kind); return <div key={source.id} className="flex items-center gap-3 rounded-xl border border-line bg-raise px-4 py-3.5"><div className="flex h-9 w-9 items-center justify-center rounded-lg" style={{ background: `${info.hue}18` }}><info.Icon size={17} style={{ color: info.hue }} /></div><div className="min-w-0 flex-1"><p className="text-[13px] font-medium">{source.display_name}</p><div className="flex items-center gap-1.5"><CheckCircle2 size={11} className={source.status === "connected" ? "text-mint" : "text-ember"} /><Mono className={source.status === "connected" ? "text-mint" : "text-ember"}>{source.status}</Mono>{source.last_synced_at && <Mono className="text-faint">· synced {relativeTime(source.last_synced_at)}</Mono>}</div>{source.last_error && <p className="text-[11px] text-ember">{source.last_error}</p>}</div><button onClick={() => void disconnect(source.id)} className="p-1.5 text-faint hover:text-ember" aria-label="Disconnect"><Trash2 size={14} /></button></div>; })}</div></section>{adding && <section className="mb-8 rounded-xl border border-iris/25 bg-raise p-5"><Mono className="mb-4 text-iris">Choose a source to connect</Mono><div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4">{available.filter((item) => !sources.some((source) => source.source_kind === item.kind)).map((item) => { const info = infoFor(item.kind); return <button key={item.kind} onClick={() => void connect(item.kind)} disabled={!item.configured} className="flex flex-col items-center gap-2 rounded-xl border border-line bg-raise py-4 hover:border-iris/40 disabled:cursor-not-allowed disabled:opacity-35"><info.Icon size={20} style={{ color: info.hue }} /><Mono className="text-quiet">{info.label}</Mono></button>; })}</div></section>}<section><Mono className="mb-3 text-faint">Workspace</Mono><div className="rounded-xl border border-line bg-raise">{[["Plan", "Pro"], ["AI budget (today)", "tracking"], ["Automations", "active"]].map(([name, value]) => <div key={name} className="flex items-center justify-between border-b border-line px-4 py-3 last:border-0"><span className="text-[13px] text-quiet">{name}</span><Mono className="text-paper">{value}</Mono></div>)}</div></section></div>;
}

function AdsPage() {
  const [postId, setPostId] = useState(""); const [pageId, setPageId] = useState(""); const [accountId, setAccountId] = useState(""); const [budget, setBudget] = useState("10"); const [days, setDays] = useState("7"); const [preview, setPreview] = useState(false); const [confirming, setConfirming] = useState(false); const [launched, setLaunched] = useState(false);
  const total = Number(budget) * Number(days);
  const fields: [string, string, (value: string) => void][] = [["Campaign name", "Black Friday boost", () => undefined], ["Post ID", "The published post ID from your Page", setPostId], ["Page ID", "Your Facebook Page numeric ID", setPageId], ["Ad Account ID", "act_XXXXXXXXXX", setAccountId]];
  return <div className="flex-1 overflow-y-auto px-5 py-6 lg:px-8"><h1 className="mb-1 text-xl font-semibold">Ad Campaigns</h1><p className="mb-6 text-sm text-quiet">Boost a post or launch a search campaign. Spend cap enforced before anything moves.</p>{launched && <div className="mb-5 flex items-start gap-3 rounded-xl border border-mint/25 bg-mint/[.06] p-4"><Check size={16} className="text-mint" /><p className="text-sm">Campaign launched and pending review.</p></div>}<div className="mb-6 flex gap-2"><Chip tone="iris" active>Boost a post</Chip><Chip tone="iris">Search campaign</Chip></div><div className="max-w-lg space-y-4 rounded-xl border border-line bg-raise p-6"><div className="rounded-lg border border-amber/25 bg-amber/[.06] px-3 py-2"><p className="text-xs text-amber">Connect a Meta account in Settings to enable boosting.</p></div>{fields.map(([name, placeholder, setter]) => <div key={name}><label className="mb-1 block text-xs text-quiet">{name}</label><input placeholder={placeholder} onChange={(event) => setter(event.target.value)} className="w-full rounded-lg border border-line bg-panel px-3 py-2 text-[13px] outline-none focus:border-iris" /></div>)}<div className="grid grid-cols-2 gap-3"><div><label className="mb-1 block text-xs text-quiet">Daily budget (USD)</label><input type="number" value={budget} onChange={(event) => setBudget(event.target.value)} className="w-full rounded-lg border border-line bg-panel px-3 py-2 text-[13px]" /></div><div><label className="mb-1 block text-xs text-quiet">Duration (days)</label><input type="number" value={days} onChange={(event) => setDays(event.target.value)} className="w-full rounded-lg border border-line bg-panel px-3 py-2 text-[13px]" /></div></div><div className="rounded-lg bg-panel px-3 py-2"><Mono className="text-faint">Total spend: </Mono><span className="font-semibold text-mint">${total.toFixed(2)}</span></div><Button small onClick={() => setPreview(true)} disabled={!postId || !pageId || !accountId}><Eye size={13} className="mr-1 inline" />Preview campaign</Button>{preview && <div className="rounded-lg border border-iris/25 bg-iris/[.06] px-4 py-3"><p className="mb-2 text-[13px]">Total: <span className="text-mint">${total.toFixed(2)}</span> over {days} days</p><Button primary small onClick={() => setConfirming(true)}><Zap size={13} className="mr-1 inline" />Launch campaign</Button></div>}</div>{confirming && <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-2xl border border-line bg-raise p-6"><div className="mb-4 flex items-center gap-3"><AlertTriangle size={18} className="text-amber" /><h2 className="font-semibold">Confirm ad spend</h2></div><p className="mb-5 text-[13px] leading-relaxed text-quiet">You are about to commit <span className="font-semibold text-paper">${total.toFixed(2)}</span> to Meta. This charge happens immediately on the provider side.</p><div className="flex gap-3"><Button primary onClick={() => { setLaunched(true); setConfirming(false); setPreview(false); }}>Confirm and launch</Button><Button onClick={() => setConfirming(false)}>Cancel</Button></div></div></div>}</div>;
}

function AppRoutes() {
  return <Switch><Route path="/" component={Landing} /><Route path="/login" component={Login} /><Route path="/inbox"><Shell><Inbox /></Shell></Route><Route path="/studio"><Shell><Studio /></Shell></Route><Route path="/people"><Shell><People /></Shell></Route><Route path="/rules"><Shell><Rules /></Shell></Route><Route path="/data"><Shell><DataPage /></Shell></Route><Route path="/settings"><Shell><SettingsPage /></Shell></Route><Route path="/ads"><Shell><AdsPage /></Shell></Route><Route><div className="flex min-h-[100dvh] items-center justify-center bg-ink"><div className="text-center"><h1 className="text-2xl font-semibold">Page not found</h1><Link href="/" className="mt-3 block text-sm text-iris">Return home</Link></div></div></Route></Switch>;
}
function App() {
  return <Router base={String(import.meta.env.BASE_URL || "").replace(/\/$/, "")}><AppRoutes /></Router>;
}
export default App;